sourceSnippets.canonicalStamp:
function canonicalStamp(v){
  const n=normText(v||'');
  if(!n||n==='none'||n==='nessuno')return 'None';
  if(n.includes('play')||n.includes('player reward')||n.includes('prize pack'))return 'Play! Pokémon';
  if(n.includes('pokemon day'))return 'Pokémon Day';
  if(n.includes('30 anniversario')||n.includes('30th celebration')||n.includes('30 celebration'))return '30° Anniversario';
  if(n.includes('pokemon center'))return 'Pokémon Center';
  if(n.includes('pre-release')||n.includes('prerelease'))return 'Pre-release';
  if(n.includes('staff'))return 'Staff';
  if(n.includes('set stamp')||n.includes('set-promo'))return 'Set Stamp';
  if(n.includes('gamestop'))return 'GameStop';
  return v||'Altro';
}

sourceSnippets.tcgdexVariantDetails:
function tcgdexVariantDetails(card){
  if(Array.isArray(card?.variants_detailed))return card.variants_detailed;
  if(Array.isArray(card?.variants))return card.variants;
  return [];
}

sourceSnippets.stampEvidenceFromTCGdex:
function stampEvidenceFromTCGdex(card,stamp){
  const st=canonicalStamp(stamp);
  const list=tcgdexVariantDetails(card);
  // TCGdex uses the exact `set-logo` taxonomy for set-logo promos.  Staff
  // copies also carry `set-logo`, so a plain Set Stamp must explicitly exclude
  // rows that also carry `staff`.  If this taxonomy is absent, preserve the
  // older lexical aliases below.
  if(st==='Set Stamp'){
    const setLogoRows=list.filter(x=>(Array.isArray(x?.stamp)?x.stamp:[]).map(normText).includes('setlogo'));
    if(setLogoRows.length){
      return setLogoRows.some(x=>!(Array.isArray(x?.stamp)?x.stamp:[]).map(normText).includes('staff'));
    }
  }
  const tokens={
    'Play! Pokémon':['playerrewards','playpokemon','prizepack','league'],
    'Pokémon Day':['pokemonday'],
    '30° Anniversario':['30thcelebration','30anniversario','30thanniversary'],
    'Pokémon Center':['pokemoncenter'],
    'Pre-release':['prerelease','prereleasepromo'],
    'Staff':['staff'],
    'Set Stamp':['setstamp','setpromo'],
    'GameStop':['gamestop']
  }[st]||[];
  if(!tokens.length)return false;
  return list.some(x=>{
    const vals=[...(Array.isArray(x?.stamp)?x.stamp:[]),x?.foil,x?.name,x?.variant].filter(Boolean).map(normText);
    return vals.some(v=>tokens.some(t=>v.includes(t)));
  });
}
